// The UI asset's PNGs in one ZIP, as the website's download builds it.
// For a split template:
// ```
// <name>/<name>.png                         the whole layout
// <name>/elements/<element>.png             an element with no states
// <name>/elements/<element>/<element>.png   an element with states
// <name>/elements/<element>/<state>.png     each of its states
// metadata.json                             {"ui_assets": [{id, name, prompt, kind, file,
//
//	size, group_id, parent_id, nine_slice}]}
//
// ```
// A template not split yet, an element or a state gives its one PNG + metadata.json.
//
//	GET /ui-assets/{ui_asset_id}/zip
func (c *Client) GetUIAssetZip(ctx context.Context, uiAssetID uuid.UUID) (io.ReadCloser, error) {
	u := c.baseURL.JoinPath("ui-assets", uiAssetID.String(), "zip")
	req := (&http.Request{
		Header: http.Header{
			"Authorization": []string{c.bearer},
			"User-Agent":    []string{c.userAgent},
		},
		Host:       u.Host,
		Method:     http.MethodGet,
		Proto:      "HTTP/1.1",
		ProtoMajor: 1,
		ProtoMinor: 1,
		URL:        u,
	}).WithContext(ctx)

	rsp, ia, err := c.do(req)
	if err != nil {
		return nil, err
	}

	// the body is left open only when it is handed to the caller
	streaming := false
	defer func() {
		if !streaming {
			rsp.Body.Close()
		}
	}()

	switch rsp.StatusCode {
	case http.StatusOK:
		// ZIP
		switch mt, _, _ := strings.Cut(rsp.Header.Get("Content-Type"), ";"); mt {
		case "application/zip":
			streaming = true

			return rsp.Body, nil
		default:
			return nil, c.failed(ia, api.NewErrUnknownContentType(rsp))
		}
	case http.StatusUnauthorized:
		// Invalid API token
		return nil, fmt.Errorf("GetUIAssetZip: status %s", rsp.Status)
	case http.StatusNotFound:
		// UI asset not found
		return nil, fmt.Errorf("GetUIAssetZip: status %s", rsp.Status)
	case http.StatusUnprocessableEntity:
		// Validation Error
		switch mt, _, _ := strings.Cut(rsp.Header.Get("Content-Type"), ";"); mt {
		case "application/json":
			var out HTTPValidationError
			if err := json.UnmarshalRead(rsp.Body, &out, jsonOpts); err != nil {
				if ia == nil {
					return nil, api.WrapDecodingError(rsp, err)
				}

				if kerr := c.keep(ia); kerr != nil {
					return nil, errors.Join(api.WrapDecodingError(rsp, err), kerr)
				}

				out = *new(HTTPValidationError)
				if err := json.Unmarshal(ia.Response.Body, &out, jsonOptsLenient); err != nil {
					return nil, api.WrapDecodingError(rsp, err)
				}
			}

			return nil, api.NewErrCustom(rsp, &out)
		default:
			return nil, c.failed(ia, api.NewErrUnknownContentType(rsp))
		}
	case http.StatusLocked:
		// Still generating; retry after Retry-After seconds
		return nil, fmt.Errorf("GetUIAssetZip: status %s", rsp.Status)
	default:
		return nil, c.failed(ia, api.NewErrUnknownStatusCode(rsp))
	}
}

// Convert between a bust portrait and a full-body character sprite.
//
// Pick the conversion with `direction`:
// - `portrait_to_character`: a bust portrait in → a full-body character sprite out.
// - `character_to_portrait`: a full-body character in → a bust portrait out.
//
// The output preserves the subject's identity/outfit while matching an internal
// size-specific pixel-art style. Returns immediately with a background job ID. Poll
// `GET /v2/background-jobs/{job_id}` to check status and retrieve the result image.
//
// **Supported Sizes:** 16, 32, 48, 64, 128, 160 px (128/160 are drawn with extra detail).
//
// **Usage Pattern:**
// 1. POST to this endpoint (returns `background_job_id`)
// 2. Poll `GET /v2/background-jobs/{background_job_id}` every 5-10 seconds
// 3. When `status` is `completed`, the sprite is in `last_response.images[0]`
//
// Using the Python client:
// ```python
// import pixellab
//
// client = pixellab.Client(secret="YOUR_API_TOKEN")
//
// response = client.portrait_character_pro(
//
//	direction="portrait_to_character",
//	image=portrait_image,
//	view="low top-down",
//	result_size=64,
//
// )
// response.images[0].pil_image().save("character.png")
// ```
//
//	POST /portrait-character-pro
